 "content": "from collections import Counter


def transform(grid):
    """Extend broken horizontal bars through their gaps and complete vertical channels."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Long, multi-cell horizontal runs are the horizontal guide bars.
    guide_rows = [r for r, row in enumerate(grid) if sum(v != 0 for v in row) >= 5]
    if not guide_rows:
        return out
    last_guide = max(guide_rows)

    # Lower vertical marks identify the columns along which the bars are completed.
    channel_cols = [c for c in range(w) if any(grid[r][c] != 0 for r in range(last_guide + 1, h))]
    for c in channel_cols:
        lower = [grid[r][c] for r in range(last_guide + 1, h) if grid[r][c] != 0]
        if not lower:
            continue
        base_color = Counter(lower).most_common(1)[0][0]

        # A guide bar belongs to this channel when equal-colored bar cells flank it.
        crossings = []
        for r in guide_rows:
            left = next((grid[r][j] for j in range(c - 1, -1, -1) if grid[r][j] != 0), 0)
            right = next((grid[r][j] for j in range(c + 1, w) if grid[r][j] != 0), 0)
            if left != 0 and left == right:
                crossings.append((r, left))

        if not crossings:
            continue

        # Between guide bars, the channel carries the color of the next bar;
        # below the final bar it carries the color of the lower vertical mark.
        crossings.sort()
        first_r, first_color = crossings[0]
        for r in range(0, first_r + 1):
            out[r][c] = first_color
        for (prev_r, _), (next_r, color) in zip(crossings, crossings[1:]):
            for r in range(prev_r + 1, next_r + 1):
                out[r][c] = color
        last_r = crossings[-1][0]
        for r in range(last_r + 1, h):
            out[r][c] = base_color

    return out
